import{d as t}from"./chunks/yaml-data.data.BuzzS5Cu.js";import{M as r}from"./chunks/theme.DWsLkQcp.js";import{z as n,J as c,ab as o,x as l,u as s}from"./chunks/framework.C9-KCiTM.js";const m=JSON.parse('{"title":"Subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"devices/api/subscriptions/index.md","filePath":"devices/api/subscriptions/index.md"}'),d={name:"devices/api/subscriptions/index.md"},v=Object.assign(d,{setup(p){const a=t.messages[15].examples.find(i=>i.name==="Subscription request");return(i,e)=>(n(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793272434000"},[e[0]||(e[0]=o('<h1 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h1><p>Subscriptions are a record of a request to receive specific message types at a requested interval.</p><p>These make use of the <a href="/docs/pr/34/devices/api/protocol/headers#5-method">Method header (5)</a>, and possible values of <code>SUBSCRIBE</code> and <code>UNSUBSCRIBE</code>, followed by additional headers to define other subscription related information.</p><ul><li><a href="/docs/pr/34/devices/api/protocol/headers#6-interval">Interval (6)</a></li><li><a href="/docs/pr/34/devices/api/protocol/headers#7-duration">Duration (7)</a></li><li><a href="/docs/pr/34/devices/api/protocol/headers#8-timeout">Timeout (8)</a></li><li><a href="/docs/pr/34/devices/api/protocol/headers#15-storage-level">Storage Level (15)</a></li><li><a href="/docs/pr/34/devices/api/protocol/headers#16-message-level">Message Level (16)</a></li><li><a href="/docs/pr/34/devices/api/protocol/headers#17-subscription-id">Subscription ID (17)</a>, see <a href="#ids">IDs</a> section below.</li></ul><h2 id="default-subscriptions" tabindex="-1">Default Subscriptions <a class="header-anchor" href="#default-subscriptions" aria-label="Permalink to &quot;Default Subscriptions&quot;">​</a></h2><h3 id="chasm-link" tabindex="-1">Chasm Link <a class="header-anchor" href="#chasm-link" aria-label="Permalink to &quot;Chasm Link&quot;">​</a></h3><div class="custom-block alpha"><p class="custom-block-title">🧪 Alpha Default Subscriptions</p><p>This default subscriptions are still being developed, and if you explicitly want data at a set interval, you should send your own subscriptions.</p></div><p>By default, when a device connects to the Chasm link, subscriptions for <a href="/docs/pr/34/devices/api/messages/15-position">Position messages</a> and <a href="/docs/pr/34/devices/api/messages/34-device-status">Status messages</a> are created automatically.</p><ul><li>Position: Valid only, RAM, 1000ms</li><li>Status: Changes only, RAM, 500ms</li></ul><p>These can be altered by sending new subscription requests with different parameters for ID <code>0</code>, or with no ID. Alternatively they can be explicitly UNSUBSCRIBED.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="position-subscription-request" tabindex="-1">Position Subscription Request <a class="header-anchor" href="#position-subscription-request" aria-label="Permalink to &quot;Position Subscription Request&quot;">​</a></h3><p>A real subscription request for position data: No message level specified, RAM storage, every 1000ms, with implied Subscription ID <code>0</code>.</p>',13)),l(r,{byteString:s(a).bytes,"yaml-data":s(t),defaultCollapsed:!1,realDeviceInfo:s(a).real},null,8,["byteString","yaml-data","realDeviceInfo"]),e[1]||(e[1]=o('<h2 id="ids" tabindex="-1">IDs <a class="header-anchor" href="#ids" aria-label="Permalink to &quot;IDs&quot;">​</a></h2><div class="custom-block alpha"><p class="custom-block-title">🧪 Alpha</p><p>New feature, subject to alterations, for advanced usage</p></div><p>Subscription IDs are an advanced feature, and can be used to uniquely identify multiple different subscriptions for the same message type.</p><p>Subscriptions that do not include a Subscription ID are considered to have a default ID of <code>0</code>. This includes any <a href="#default-subscriptions">default subscriptions</a></p><h3 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h3><p>When creating a subscription, you can optionally include the <a href="/docs/pr/34/devices/api/protocol/headers#17-subscription-id">Subscription ID (17)</a> header.</p><p>Only one subscription per message type and Subscription ID combination can exist at a time. If a new subscription is created with the same message type and Subscription ID as an existing subscription, the existing subscription will be replaced.</p><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;Responses&quot;">​</a></h3><p>When a message is generated as part of a subscription, the Subscription ID header may be included to indicate which subscription this message is fulfilling.</p><p>In the case that the subscription was created without a Subscription ID (defaulting to <code>0</code>), the Subscription ID header will be omitted from the message.</p>',10))]))}});export{m as __pageData,v as default};
